import { describe, it, expect } from 'vitest';
import { Project } from 'ts-morph';
import { extractProperties } from '../ts-extractor';

/**
 * 从 interface 声明创建 ts-morph Type 对象
 */
function getObjectType(interfaceStr: string) {
  const project = new Project({ useInMemoryFileSystem: true });
  const sourceFile = project.createSourceFile('test.ts', `${interfaceStr}\ntype T = Params;`);
  const typeAlias = sourceFile.getTypeAliasOrThrow('T');
  return typeAlias.getType();
}

describe('extractProperties', () => {
  it('简单对象 — 正确提取属性名、类型、required', () => {
    const type = getObjectType('interface Params { name: string; age: number }');
    const props = extractProperties(type);

    expect(props).toHaveLength(2);

    const nameProp = props.find(p => p.name === 'name')!;
    expect(nameProp.type).toBe('string');
    expect(nameProp.required).toBe(true);

    const ageProp = props.find(p => p.name === 'age')!;
    expect(ageProp.type).toBe('number');
    expect(ageProp.required).toBe(true);
  });

  it('可选属性 — age? 的 required 为 false', () => {
    const type = getObjectType('interface Params { name: string; age?: number }');
    const props = extractProperties(type);

    expect(props).toHaveLength(2);

    const nameProp = props.find(p => p.name === 'name')!;
    expect(nameProp.required).toBe(true);

    const ageProp = props.find(p => p.name === 'age')!;
    expect(ageProp.required).toBe(false);
    expect(ageProp.type).toBe('number');
  });

  it('枚举属性 — 提取 enumValues', () => {
    const type = getObjectType(`interface Params { role: 'admin' | 'user' }`);
    const props = extractProperties(type);

    expect(props).toHaveLength(1);
    const roleProp = props[0];
    expect(roleProp.name).toBe('role');
    expect(roleProp.type).toBe('string');
    expect(roleProp.enumValues).toEqual(['admin', 'user']);
  });

  it('嵌套对象 — 递归提取 properties', () => {
    const type = getObjectType('interface Params { filter: { min: number; max: number } }');
    const props = extractProperties(type);

    expect(props).toHaveLength(1);
    const filterProp = props[0];
    expect(filterProp.name).toBe('filter');
    expect(filterProp.type).toBe('object');
    expect(filterProp.properties).toBeDefined();
    expect(filterProp.properties).toHaveLength(2);

    const minProp = filterProp.properties!.find(p => p.name === 'min')!;
    expect(minProp.type).toBe('number');

    const maxProp = filterProp.properties!.find(p => p.name === 'max')!;
    expect(maxProp.type).toBe('number');
  });

  it('数组属性 — type 为 array, itemType 为 string', () => {
    const type = getObjectType('interface Params { tags: string[] }');
    const props = extractProperties(type);

    expect(props).toHaveLength(1);
    const tagsProp = props[0];
    expect(tagsProp.name).toBe('tags');
    expect(tagsProp.type).toBe('array');
    expect(tagsProp.itemType).toBe('string');
  });
});

import { describe, it, expect } from 'vitest';
import { Project } from 'ts-morph';
import { mapType } from '../ts-extractor';

/**
 * 从类型字符串创建 ts-morph Type 对象
 */
function getTypeFromSource(typeStr: string) {
  const project = new Project({ useInMemoryFileSystem: true });
  const sourceFile = project.createSourceFile('test.ts', `type T = ${typeStr};`);
  const typeAlias = sourceFile.getTypeAliasOrThrow('T');
  return typeAlias.getType();
}

describe('mapType', () => {
  describe('基础类型', () => {
    it('string → "string"', () => {
      expect(mapType(getTypeFromSource('string'))).toBe('string');
    });

    it('number → "number"', () => {
      expect(mapType(getTypeFromSource('number'))).toBe('number');
    });

    it('boolean → "boolean"', () => {
      expect(mapType(getTypeFromSource('boolean'))).toBe('boolean');
    });
  });

  describe('字面量类型', () => {
    it('"hello" → "string"', () => {
      expect(mapType(getTypeFromSource('"hello"'))).toBe('string');
    });

    it('42 → "number"', () => {
      expect(mapType(getTypeFromSource('42'))).toBe('number');
    });

    it('true → "boolean"', () => {
      expect(mapType(getTypeFromSource('true'))).toBe('boolean');
    });
  });

  describe('数组类型', () => {
    it('string[] → "array"', () => {
      expect(mapType(getTypeFromSource('string[]'))).toBe('array');
    });

    it('number[] → "array"', () => {
      expect(mapType(getTypeFromSource('number[]'))).toBe('array');
    });
  });

  describe('联合类型', () => {
    it('"a" | "b" → "string"（字面量联合）', () => {
      expect(mapType(getTypeFromSource('"a" | "b"'))).toBe('string');
    });

    it('1 | 2 → "number"（数字字面量联合）', () => {
      expect(mapType(getTypeFromSource('1 | 2'))).toBe('number');
    });

    it('number | undefined → "number"（可选联合，剥离 undefined）', () => {
      expect(mapType(getTypeFromSource('number | undefined'))).toBe('number');
    });

    it('string | null → "string"（剥离 null）', () => {
      expect(mapType(getTypeFromSource('string | null'))).toBe('string');
    });
  });

  describe('对象类型', () => {
    it('{ foo: string } → "object"', () => {
      expect(mapType(getTypeFromSource('{ foo: string }'))).toBe('object');
    });
  });

  describe('特殊类型', () => {
    it('null → "string"（降级）', () => {
      expect(mapType(getTypeFromSource('null'))).toBe('string');
    });

    it('undefined → "string"（降级）', () => {
      expect(mapType(getTypeFromSource('undefined'))).toBe('string');
    });

    it('any → "string"（降级）', () => {
      expect(mapType(getTypeFromSource('any'))).toBe('string');
    });

    it('unknown → "string"（降级）', () => {
      expect(mapType(getTypeFromSource('unknown'))).toBe('string');
    });
  });
});

import { describe, it, expect, vi } from 'vitest';
import { transformCode } from 'webmcp-nexus-core';
import webmcpLoader from '../loader';

vi.mock('webmcp-nexus-core', () => ({
  transformCode: vi.fn(),
}));

const mockedTransformCode = vi.mocked(transformCode);

function createLoaderContext(resourcePath: string, options: Record<string, unknown> = {}) {
  return {
    resourcePath,
    getOptions: () => options,
    emitWarning: vi.fn(),
  } as any;
}

/** Simulate webpack v4 loader context (no getOptions, uses this.query) */
function createV4LoaderContext(
  resourcePath: string,
  query: unknown = {},
) {
  return {
    resourcePath,
    query,
    // No getOptions — simulates webpack v4
    emitWarning: vi.fn(),
  } as any;
}

describe('webmcpLoader', () => {
  it('should return original source when transformCode returns transformed: false', () => {
    const source = 'const foo = 1;';
    mockedTransformCode.mockReturnValue({ code: source, transformed: false });

    const context = createLoaderContext('/project/src/foo.ts');
    const result = webmcpLoader.call(context, source);

    expect(mockedTransformCode).toHaveBeenCalledWith(source, '/project/src/foo.ts', {
      projectRoot: undefined,
    });
    expect(result).toBe(source);
  });

  it('should return transformed code when source contains registerGlobalTools', () => {
    const source = 'registerGlobalTools({ search: searchTool });';
    const transformed = '// injected schema\nregisterGlobalTools({ search: searchTool });';
    mockedTransformCode.mockReturnValue({
      code: transformed,
      transformed: true,
    });

    const context = createLoaderContext('/project/src/tools.ts');
    const result = webmcpLoader.call(context, source);

    expect(mockedTransformCode).toHaveBeenCalledWith(source, '/project/src/tools.ts', {
      projectRoot: undefined,
    });
    expect(result).toBe(transformed);
  });

  it('should pass resourcePath as filePath to transformCode', () => {
    const source = 'some code';
    mockedTransformCode.mockReturnValue({ code: source, transformed: false });

    const context = createLoaderContext('/my/project/src/app.tsx');
    webmcpLoader.call(context, source);

    expect(mockedTransformCode).toHaveBeenCalledWith(source, '/my/project/src/app.tsx', {
      projectRoot: undefined,
    });
  });
});

describe('webmcpLoader (webpack v4 fallback)', () => {
  it('should read options from this.query when getOptions is unavailable', () => {
    const source = 'const foo = 1;';
    mockedTransformCode.mockReturnValue({ code: source, transformed: false });

    const context = createV4LoaderContext('/project/src/tools.ts', {
      projectRoot: '/project',
      alias: { '@utils': '/project/src/utils' },
    });
    webmcpLoader.call(context, source);

    expect(mockedTransformCode).toHaveBeenCalledWith(source, '/project/src/tools.ts', {
      projectRoot: '/project',
      alias: { '@utils': '/project/src/utils' },
    });
  });

  it('should fallback to empty options when this.query is a string (query string)', () => {
    const source = 'const foo = 1;';
    mockedTransformCode.mockReturnValue({ code: source, transformed: false });

